import pytest


def shout(xs: list[str]) -> None:
    """Print each string in xs upper-cased, one per line."""
    for s in xs:
        print(s.upper())


def test_shout_basic(capsys: pytest.CaptureFixture[str]) -> None:
    shout(["hello", "World"])
    assert capsys.readouterr().out == "HELLO\nWORLD\n"


def test_shout_empty(capsys: pytest.CaptureFixture[str]) -> None:
    shout([])
    assert capsys.readouterr().out == ""


def test_shout_already_upper_and_mixed(capsys: pytest.CaptureFixture[str]) -> None:
    shout(["ABC", "aBc", "a1!b"])
    assert capsys.readouterr().out == "ABC\nABC\nA1!B\n"


def test_shout_empty_string_prints_blank_line(
    capsys: pytest.CaptureFixture[str],
) -> None:
    shout(["", "x"])
    assert capsys.readouterr().out == "\nX\n"


def test_shout_unicode(capsys: pytest.CaptureFixture[str]) -> None:
    shout(["straße", "éa"])
    assert capsys.readouterr().out == "STRASSE\nÉA\n"


def test_shout_does_not_mutate_input() -> None:
    xs = ["a", "b"]
    shout(xs)
    assert xs == ["a", "b"]


def test_shout_returns_none() -> None:
    assert shout(["a"]) is None  # type: ignore[func-returns-value]

